	bool ContainsKey(const void* key) const;	bool ContainsValue(const void* value) const;	const void* GetValue(const void* key) const;	bool GetValueIfPresent(const void* key, const void** value) const;	void GetKeysAndValues(const void** keys, const void** values) const;	void ApplyFunction(CFDictionaryApplierFunction applier, void* context) const;	// Mutable CFDictionary wrappings	static CFMutableDictionaryRef CreateMutable(CFAllocatorRef allocator,												CFIndex capacity, 												const CFDictionaryKeyCallBacks* keyCallBacks, 												const CFDictionaryValueCallBacks* valueCallBacks);	static CFMutableDictionaryRef CreateMutableCopy(CFAllocatorRef allocator, 													CFIndex capacity, 													CFDictionaryRef theDict);	void AddValue(const void* key, const void* value);	void SetValue(const void* key, const void* value);	void ReplaceValue(const void* key, const void* value);	void RemoveValue(const void* key);	void RemoveAllValues();};//========================================================================================// CAutoCFDictionary_AC//========================================================================================class CAutoCFDictionary_AC : public TemplateAutoRef_AC<CFDictionaryRef>{public:	CAutoCFDictionary_AC();	CAutoCFDictionary_AC(CFDictionaryRef theDict);	CAutoCFDictionary_AC(const void** keys, const void** values, CFIndex numValues, 						 const CFDictionaryKeyCallBacks* keyCallBacks, 						 const CFDictionaryValueCallBacks* valueCallBacks);	CAutoCFDictionary_AC(CFAllocatorRef allocator, CFDictionaryRef theDict);	CAutoCFDictionary_AC(const TemplateAutoRef_AC<CFDictionaryRef>& from);	~CAutoCFDictionary_AC();};//========================================================================================// CAutoCFMutableDictionary_AC//========================================================================================class CAutoCFMutableDictionary_AC : public TemplateAutoRef_AC<CFMutableDictionaryRef>{public:	CAutoCFMutableDictionary_AC();	CAutoCFMutableDictionary_AC(CFMutableDictionaryRef theDict);	CAutoCFMutableDictionary_AC(CFIndex capacity, const CFDictionaryKeyCallBacks* keyCallBacks, 								const CFDictionaryValueCallBacks* valueCallBacks);	CAutoCFMutableDictionary_AC(CFIndex capacity, CFDictionaryRef theDict);	CAutoCFMutableDictionary_AC(const TemplateAutoRef_AC<CFMutableDictionaryRef>& from);	~CAutoCFMutableDictionary_AC();};//========================================================================================// __CFDictionary//========================================================================================inline CFIndex __CFDictionary::GetCount() const{	return CFDictionaryGetCount(this);}inline CFIndex __CFDictionary::GetCountOfKey(const void* key) const{	return CFDictionaryGetCountOfKey(this, key);}inline CFIndex __CFDictionary::GetCountOfValue(const void* value) const{	return CFDictionaryGetCountOfValue(this, value);}inline bool __CFDictionary::ContainsKey(const void* key) const{	return CFDictionaryContainsKey(this, key);}inline bool __CFDictionary::ContainsValue(const void* value) const{	return CFDictionaryContainsValue(this, value);}inline const void* __CFDictionary::GetValue(const void* key) const{	return CFDictionaryGetValue(this, key);}inline bool __CFDictionary::GetValueIfPresent(const void* key, const void** value) const{	return CFDictionaryGetValueIfPresent(this, key, value);}inline void __CFDictionary::GetKeysAndValues(const void** keys, const void** values) const{	CFDictionaryGetKeysAndValues(this, keys, values);}inline void __CFDictionary::ApplyFunction(CFDictionaryApplierFunction applier, void* context) const{	CFDictionaryApplyFunction(this, applier, context);}inline void __CFDictionary::AddValue(const void* key, const void* value){	CFDictionaryAddValue(this, key, value);}inline void __CFDictionary::SetValue(const void* key, const void* value){	CFDictionarySetValue(this, key, value);}inline void __CFDictionary::ReplaceValue(const void* key, const void* value){	CFDictionaryReplaceValue(this, key, value);}inline void __CFDictionary::RemoveValue(const void* key){	CFDictionaryRemoveValue(this, key);}inline void __CFDictionary::RemoveAllValues(){	CFDictionaryRemoveAllValues(this);}//========================================================================================// CAutoCFDictionary_AC//========================================================================================inline CAutoCFDictionary_AC::CAutoCFDictionary_AC()	:	TemplateAutoRef_AC<CFDictionaryRef>(){}inline CAutoCFDictionary_AC::CAutoCFDictionary_AC(CFDictionaryRef theDict)	:	TemplateAutoRef_AC<CFDictionaryRef>(theDict){}inline CAutoCFDictionary_AC::CAutoCFDictionary_AC(const void** keys, const void** values, CFIndex numValues, 												  const CFDictionaryKeyCallBacks* keyCallBacks, 												  const CFDictionaryValueCallBacks* valueCallBacks)	:	TemplateAutoRef_AC<CFDictionaryRef>(__CFDictionary::Create(NULL, keys, values, numValues, keyCallBacks, valueCallBacks)){}inline CAutoCFDictionary_AC::CAutoCFDictionary_AC(CFAllocatorRef allocator, CFDictionaryRef theDict)	:	TemplateAutoRef_AC<CFDictionaryRef>(__CFDictionary::CreateCopy(allocator, theDict)){}inline CAutoCFDictionary_AC::CAutoCFDictionary_AC(const TemplateAutoRef_AC<CFDictionaryRef>& from)	:	TemplateAutoRef_AC<CFDictionaryRef>(from){}inline CAutoCFDictionary_AC::~CAutoCFDictionary_AC(){}//========================================================================================// CAutoCFMutableDictionary_AC//========================================================================================inline CAutoCFMutableDictionary_AC::CAutoCFMutableDictionary_AC()	:	TemplateAutoRef_AC<CFMutableDictionaryRef>(){}inline CAutoCFMutableDictionary_AC::CAutoCFMutableDictionary_AC(CFMutableDictionaryRef theDict)	:	TemplateAutoRef_AC<CFMutableDictionaryRef>(theDict){}inline CAutoCFMutableDictionary_AC::CAutoCFMutableDictionary_AC(CFIndex capacity, 																const CFDictionaryKeyCallBacks* keyCallBacks, 																const CFDictionaryValueCallBacks* valueCallBacks)	:	TemplateAutoRef_AC<CFMutableDictionaryRef>(__CFDictionary::CreateMutable(NULL, capacity, keyCallBacks, valueCallBacks)){}inline CAutoCFMutableDictionary_AC::CAutoCFMutableDictionary_AC(CFIndex capacity, CFDictionaryRef theDict)	:	TemplateAutoRef_AC<CFMutableDictionaryRef>(__CFDictionary::CreateMutableCopy(NULL, capacity, theDict)){}inline CAutoCFMutableDictionary_AC::CAutoCFMutableDictionary_AC(const TemplateAutoRef_AC<CFMutableDictionaryRef>& from)	:	TemplateAutoRef_AC<CFMutableDictionaryRef>(from){}inline CAutoCFMutableDictionary_AC::~CAutoCFMutableDictionary_AC(){}#endif // __CCFDictionary_AC__